"""Appréciations CODEX après lecture des 18 supports de la série autorisée.

Les citations des scans sont transcrites depuis les vues, celles des PDF avec
texte et des EML sont prélevées dans le support. Aucun verdict automatique.
"""
from datetime import datetime, timezone
from email import policy
from email.parser import BytesParser
from pathlib import Path

from .commun import ARTEFACTS, lire_json, empreinte, octets_json, ecrire_identique_ou_nouveau
from .ancrage import charger_constat
from .serie_1 import verifier_serie

LECTURES = ARTEFACTS / "serie_1/lectures"

SCANS = {
    "19-serment":("Affirmé solennellement devant moi\nA Montréal, ce 19 novembre 2015", "P-19, page PDF 12/16, affidavit, jurat ; signature d'Élise et réitération des allégués aux points 2–3. Copie de l'affidavit aussi p.16."),
    "19-marginalite":("En effet, le défendeur ne s’impliquait que minimalement dans les soins d’Alexia, laissant toute la responsabilité à la demanderesse, ce qui causait de grandes frictions dans le couple;", "P-19, page PDF 4/16, §6 de la requête."),
    "19-therapie":("En 2011, suite à une infidélité du défendeur, les parties ont vécu séparées pendant un (1) an et ont été en thérapie. A ce moment il est ressorti que le défendeur avait de la difficulté à assumer son rôle de père et s’investir;", "P-19, page PDF 4/16, §7."),
    "19-dpj":("Les enfants ne font pas l’objet d’une décision de la Cour du Québec, chambre de la jeunesse ni d’une instance en cours, ni d’une entente avec le directeur de la protection de la jeunesse;", "P-19, page PDF 4/16, §3 ; requête entière également lue pour la non-reprise des allégations de violence."),
    "19-disponibilite":("En effet, les enfants sont jeunes et de plus, le défendeur était rarement disponible pour prendre soins d’eux;", "P-19, page PDF 5/16, §15 ; §§16–17 sur les soins et l'aide lors des indisponibilités maternelles également lus."),
    "19-partage":("Dès la rupture, le défendeur voulait instaurer une garde partagée, que la demanderesse a refusé puisque contraire à l’intérêt des enfants;", "P-19, page PDF 4/16, §14 ; demande de garde maternelle p.5 §26 et conclusions p.10."),
    "19-entente":("Les parties ont donc convenu que la demanderesse aurait la garde des enfants, le tout tel qu’il appert des échanges de messages textes datés du 21 avril 2015, produits en liasse au soutien des présentes sous la pièce P-2", "P-19, page PDF 5/16, §18. La ‘pièce P-2’ interne à cette requête est une autre numérotation que P-2 dans le présent bordereau."),
    "42-serment":("Affirmé solennellement devant moi\nà Montréal, ce 21 octobre 2019", "P-42, page PDF 4/4, jurat ; signature d'Élise, date de signature et formule d'assermentation."),
    "42-abandon":("De facto, le défendeur en quittant le pays va abandonner ses enfants et ne va pas subvenir à leurs besoins;", "P-42, page PDF 3/4, §21 ; §§14–20 sur le travail et les ressources, p.1 §3 et p.2 §7 également lus."),
    "29-serment":("Je déclare que les renseignements donnés ci-dessus sont\nexacts et complets, en ce qui me concerne, et je signe :", "P-29, page PDF 7/8, partie 10, colonne de la mère : signature et déclaration sous serment à Longueuil, le 21 octobre 2019 ; identité p.1."),
    "40-serment":("Affirmé solennellement devant moi\nà Saint-Lambert, ce 21 juillet 2023", "P-40, page PDF 4/5, jurat et signature d'Élise ; signature de Me Ayoub p.3."),
    "40-choix":("Le demandeur a fait le choix de ne pas travailler pour subvenir aux besoins de ses enfants;", "P-40, page PDF 2/5, §8 ; titre et objet p.1, §§6–7 p.2, signatures p.3–4."),
    "40-precarite":("Malgré les prétentions du demandeur eu égard à sa précarité financière, le 4 novembre 2019, l’Honorable juge Danielle Mayrant, J.C.S., a rendu un jugement ordonnant au demandeur, malgré sa perte importante de revenus, de payer une pension alimentaire de 650$ par mois à la défenderesse et ordonnait la levée des saisies des comptes bancaires personnels de Monsieur à toutes fins que de droit;", "P-40, page PDF 2/5, §6."),
    "40-offres":("Lors de l’audition du 4 novembre 2019, il a été mis en preuve qu’une liste de plus de quatre cents offres d’emploi étaient disponibles pour des candidats ayant le profil académique et professionnel du demandeur;", "P-40, page PDF 2/5, §7."),
    "40-objet":("DÉNONCIATION DE LA DÉFENDERESSE D’UN MOYEN DÉCLINATOIRE\n(Incompétence territoriale du tribunal, article 167 du Code de procédure civile)", "P-40, page PDF 1/5, titre ; §§9–11 p.2–3 et conclusions p.3 portent sur le district et le domicile."),
    "9-routine":("Compte tenu des circonstances, nous considérons qu’il y a contre-indication à l’établissement de la garde partagée des deux (2) enfants mineurs vu leur jeune âge et qu’il n’est pas dans leur intérêt de modifier une routine établie depuis plus deux mois.", "P-9, page PDF 2/2, premier paragraphe après les horaires ; transcription visuelle contrôlée, sans corriger le ‘plus deux mois’ imprimé."),
    "9-nuitees":("Du mercredi après la garderie et ce jusqu’au jeudi matin à la garderie;\nDu samedi 14h 00 au dimanche 16h00", "P-9, page PDF 2/2, Semaine 1 ; Semaine 2 offre aussi mercredi–jeudi."),
    "18-premature":("Nous nous réjouissons d’apprendre que votre client est tout à fait disposé à établir une progression dans ses droits d’accès auprès des enfants. Toutefois, notre cliente considère qu’il est prématuré à ce stade ci d’entrevoir l’aménagement d’une garde partagée dès février 2016.", "P-18, page PDF 1/5, dernier paragraphe ; texte contrôlé visuellement sur la lettre du 3 septembre 2015."),
}


def preparer():
    constat=charger_constat(ARTEFACTS / "constat_2026-10-29_p38/constat.json")
    travail=lire_json(ARTEFACTS / "travail/travail.json")
    fiches={f["lien"]["id"]:f for f in lire_json(ARTEFACTS / "fiches_2026-10-29_p38/fiches.json")["fiches"]}
    inventaire={e["cote"]:e for e in lire_json(LECTURES / "inventaire.json")}
    textes={c:Path(e["lecture"]).read_text() for c,e in inventaire.items()}
    corps={}
    for c,e in inventaire.items():
        if e["type"]=="EML local intégral":
            m=BytesParser(policy=policy.default).parsebytes(Path(e["support"]["chemin"]).read_bytes())
            corps[c]=m.get_body(preferencelist=("plain",)).get_content().replace("\r\n","\n")
    date=datetime.now(timezone.utc).isoformat(timespec="seconds");ps=[]

    def extrait(c,debut,fin):
        t=corps.get(c,textes[c]);a=t.index(debut);return t[a:t.index(fin,a)].rstrip()

    def phrase(c,debut):
        t=corps.get(c,textes[c]);a=t.index(debut);return t[a:t.find("\n",a) if "\n" in t[a:] else len(t)].rstrip()

    def ajout(lien,passage,raison,portee,limites,autres=(),ecarts=(),attribution=None):
        f=fiches[lien];cote=f["cote"]["cote"];inv=inventaire[cote]
        if isinstance(passage,str):element,localisation=SCANS[passage];methode="Transcription CODEX de la page originale rendue, contrôlée visuellement ; aucune fiche de repérage utilisée comme autorité."
        else:element,localisation=passage;methode="Extrait du texte du PDF original ou du corps MIME de l'EML local ; mots et caractères conservés, CRLF → LF pour les courriels."
        complements=[]
        for p in autres:
            t,loc=SCANS[p] if isinstance(p,str) else p
            complements.append({"texte":t,"localisation":loc})
        perimetre=(f"PDF original entier, {inv['pages']} pages ; lecture visuelle de toutes les pages" if cote in {'P-19','P-40','P-42','P-29'} else
                   f"PDF original entier, {inv['pages']} pages ; texte intégral extrait, vues de contrôle signalées dans l'inventaire" if inv.get('pages') else
                   "EML original, From/To/Date/Subject et corps text/plain intégral avec messages antérieurs cités. Les répétitions des fils sont repérées dans une copie de lecture compacte, sans remplacer le support original.")
        o={"schema":"va-observation/1","id":f"VA06-S1-L{lien}-v1","liens":[lien],"remplace":None,
           "auteur":"CODEX","avancement":"PROPOSE","date":date,"grille_version":"1.1",
           "empreinte_enonce":f["enonce"]["empreinte_texte"],"empreintes_cotes":{str(f["cote"]["id"]):empreinte(octets_json(f["cote"]))},
           "supports":f["supports"],"resultat":"RELATION_REPEREE","element_observe":element,"localisation":localisation,
           "raison":raison,"portee":portee,"limites":limites,"ecarts":list(ecarts),"passages_supplementaires":complements,
           "perimetre_lu":perimetre,"methode_verbatim":methode,
           "controle_attribution":attribution or f"Le passage cité a été trouvé dans {cote}, {f['supports'][0]['identite']['modele']} pk {f['supports'][0]['identite']['pk']}. Les autres références du paragraphe conservent leurs liens distincts."}
        if portee=="EN_ETABLIT_UNE_PARTIE":o["reste_sans_piece"]=limites
        ps.append(o)

    ajout(1,"19-serment","L'affidavit signé par Élise réitère les allégués de la requête et porte le jurat du 19 novembre 2015. Ce support établit l'attestation de l'acte de 2015 mentionnée au §5.","EN_ETABLIT_UNE_PARTIE","Ce lien concerne la requête de 2015 ; les attestations de 2019 et de 2023 relèvent des trois autres liens du paragraphe.")
    ajout(2,"42-serment","La déclaration comporte la signature d'Élise et son affirmation solennelle datée du 21 octobre 2019. Elle établit cette attestation parmi les actes énumérés au §5.","EN_ETABLIT_UNE_PARTIE","Elle ne porte pas à elle seule les attestations de la requête de 2015, du formulaire financier P-29 et de la dénonciation de 2023.")
    ajout(3,"29-serment","La colonne de la mère porte sa signature et un serment reçu à Longueuil le 21 octobre 2019. L'identité de la mère figure au formulaire. La relation est directe avec l'attestation du formulaire alléguée au §5.","EN_ETABLIT_UNE_PARTIE","L'assermentation de P-29 ne vaut pas constat des autres actes ni validation de l'exactitude des revenus. La p.1 porte aussi ‘préparé le 2019 10 25’ et des annotations de présentation ; l'observation date le jurat lu p.7, sans confondre ces mentions.")
    ajout(4,"40-serment","Le scan contient la déclaration sous serment d'Élise relative aux faits de la dénonciation, avec jurat du 21 juillet 2023. Il établit l'attestation de cet acte décrite au §5.","EN_ETABLIT_UNE_PARTIE","La pièce de 2023 ne porte pas les attestations des actes de 2015 et 2019 et n'établit pas leur véracité objective.")
    ajout(18,"9-nuitees","La lettre offre des nuits chez le père sans énoncer de condition d'évaluation, thérapie ou amélioration préalable de sa disponibilité. Le motif exprimé contre le partage égal est l'âge et la routine récente. Les deux pages ne reprennent pas l'allégation de violence de P-2.","EN_ETABLIT_UNE_PARTIE","Constat limité au texte des deux pages. L'absence d'une condition dans cette offre n'établit ni la réalité du danger ni l'absence de toute intervention DPJ, et cette pièce ne suffit pas à décrire toutes les négociations de 2015.",autres=["9-routine"])
    ajout(19,(extrait('P-16','Les parties conviennent également','8. Dans le cadre'),'P-16, page 3/6, §7 a–e, progression des accès ; projet entier lu.'),"Le projet échelonne les nuits jusqu'en 2018, à partir de la première phase samedi–dimanche puis dimanche–mardi ; aucun palier n'est conditionné aux mesures thérapeutiques ou correctives énumérées au §9-B. Il ne reprend pas les allégations de violence de 2013.","EN_ETABLIT_UNE_PARTIE","C'est un projet non signé, dont le §21 conditionne la validité aux signatures : aucune mise en œuvre n'est tenue pour acquise. Le projet nie une décision jeunesse ou une entente DPJ au préambule, ce qui ne prouve pas l'absence de toute intervention.")
    ajout(20,(extrait('P-2','Ensuite, Alexia vie','Si j\'étais ton avocate'),'P-2, page 1/2, paragraphe violence/DPJ.'),"P-2 contient le registre de violence et de compromission auquel le §9-B compare les textes ultérieurs. Il constitue le terme initial identifiable de cette comparaison.","ECLAIRE_SEULEMENT","Le courriel de 2013 ne prouve pas le contenu des négociations de 2015 ni leur non-reprise des allégations. La possibilité d'une conclusion DPJ y est évoquée ; aucune intervention effective n'y est rapportée.")
    ajout(21,"19-dpj","La requête formule une absence de décision jeunesse, d'instance en cours ou d'entente DPJ. La lecture de la requête entière ne retrouve pas les allégations de violence conjugale de P-2 ; l'argumentation parentale est d'une autre nature.","EN_ETABLIT_UNE_PARTIE","L'absence de ces allégations dans cet acte n'établit pas l'absence générale de violence ou de toute intervention DPJ. Les consultations psychologiques d'Élise en 2015 sont expressément mentionnées au §22 ; leur existence n'est pas niée.")
    ajout(22,"19-marginalite","Le §6 attribue une implication minimale et toute la responsabilité à la mère ; les §§15–17 décrivent une rare disponibilité et une aide limitée aux indisponibilités maternelles. La marginalité est donc effectivement formulée dans P-19.","EN_ETABLIT_UNE_PARTIE","La pièce établit que ces propositions ont été faites, sans démontrer leur vérité, leur insincérité ni l'absence du même portrait dans d'autres textes.",autres=["19-disponibilite"])
    ajout(23,(extrait('P-2','Pendant toute cette procédure','Élise, malheureusement'),'P-2, page 1/2, fin du paragraphe décrivant la procédure d’urgence.'),"Le courriel annonce une routine qui s'installe pendant une garde maternelle de fait. Il ne formule pas les descriptions qualitatives précises des §§6 et 15–17 de P-19, ce qui fournit un point documentaire de comparaison pour le §9-C.","EN_ETABLIT_UNE_PARTIE","P-2 contient d'autres appréciations critiques et des allégations de violence ; leur absence n'est pas alléguée ici. Il ne prouve pas le libellé ni la fausseté de P-19.")
    ajout(24,"9-routine","Le refus de la garde partagée est motivé par l'âge et la routine établie depuis plus deux mois. La lettre ne formule pas le portrait historique d'implication minimale et de soins exclusivement maternels de P-19.","EN_ETABLIT_UNE_PARTIE","La lettre contient d'autres reproches sur les accès depuis le départ. Le constat de non-reprise vise le portrait qualitatif historique précis, sans nier ces reproches ni démontrer leur sincérité.")
    p20=extrait('P-20',"J'ai dit à l'avocat",'\n\nOui ça')
    ajout(25,(p20,'P-20, Email 16, 11 janvier 2016, 18 h 02 -0500, quatrième paragraphe de la réponse ; message du demandeur cité immédiatement après.'),"Élise dit avoir demandé à l'avocat d'enlever cette partie et situe la question à 50 % du temps. Le message cité identifie la partie relative à Alexia. Le courriel établit ce récit et le déplacement quantitatif décrits au §9-D.","EN_ETABLIT_UNE_PARTIE","Ce récit ne prouve pas indépendamment la teneur des échanges réels avec l'avocate, une demande antérieure au dépôt ni un refus exprès de l'avocate. Le désaveu documentaire de cette formulation ne retire pas automatiquement toutes les autres allégations.")
    ajout(26,"19-marginalite","La formulation du §6 de P-19 fournit le texte auquel se rapporte la réponse invoquée au §9-D : implication minimale et responsabilité maternelle entière.","ECLAIRE_SEULEMENT","P-19 ne contient pas la demande de retrait ni la réponse sur 50 % ; ces propos sont dans email_manager.Email pk 16, P-20. P-19 est ici le terme de comparaison, pas la source de la réponse.",attribution="Les mots d'Élise sur le retrait ne sont pas dans P-19 ; ils sont dans P-20, email_manager.Email pk 16, examiné au lien 25. Le §9-D les attribue bien à P-20 : pas d'écart IDENTITE_PIECE sur ce lien.")
    ajout(27,"19-partage","La requête présente le partage voulu par le père comme contraire à l'intérêt des enfants et demande une garde maternelle, sur fond d'implication et de disponibilité paternelles dépréciées. C'est le texte sur lequel porte l'interprétation soutenue au §9-F.","ECLAIRE_SEULEMENT","Le mécanisme de continuité historique est l'interprétation plaidée du demandeur. L'acte ne démontre pas à lui seul la relation réellement vécue, la rupture additionnelle ou ce que le Tribunal devait retenir.",autres=["19-marginalite","19-disponibilite"])
    ajout(28,(extrait('P-2',"Si j'étais ton avocate",'Élise, malheureusement'),'P-2, page 1/2, paragraphe décrivant le plan.'),"Le courriel présente directement un plan de garde exclusive d'urgence, sortie du père et installation d'une routine. Cette teneur explique son invocation comme pièce du noyau documentaire au §9-G.","ECLAIRE_SEULEMENT","L'invocation du patron ne signifie pas exécution identique du projet. La pièce ne démontre pas à elle seule sa continuité en 2015 ou l'intention d'autres intervenantes.")
    ajout(29,"19-entente","La requête affirme une garde maternelle convenue puis en demande la consécration ; les signatures p.11–12 identifient Élise et Me Adelia Ferreira. Ces contenus se rapportent à l'acte invoqué au §9-G.","ECLAIRE_SEULEMENT","L'acte ne prouve pas seul le patron allégué. La signature de Me Ferreira est observée ; aucune rédaction par Me Marie-Josée Ayoub n'est déduite. La cote interne P-2 de la requête n'est pas assimilée au courriel P-2 de la présente demande.")
    ajout(30,(p20,'P-20, Email 16, réponse du 11 janvier 2016 à 18 h 02 -0500, paragraphe sur le retrait et 50 %.'),"Le récit de retrait et la formulation à 50 % constituent une relation précise avec le désaveu invoqué dans le noyau documentaire du §9-G.","ECLAIRE_SEULEMENT","Ce contenu ne démontre pas isolément le patron, le concert ou l'intention consciente de chaque intervenante. Il ne prouve pas un refus exprès de l'avocate de retirer le texte.")
    ajout(31,(phrase('P-22.1',"Tu n'en as pas assez"),'P-22.1, Email 6, réponse d’Élise du 16 septembre 2016 à 18 h 25 -0400 ; premier paragraphe.'),"Élise conteste avoir traité le père d'incapable et distingue ce propos de son appréciation du lien d'attachement. Le même EML reproduit ses propos antérieurs sur la participation inférieure à 50 %. Ce membre se rapporte au noyau documentaire invoqué au §9-G.","ECLAIRE_SEULEMENT","L'observation vise ce seul membre de P-22. L'existence des déclarations et de leur discussion ne démontre pas seule le patron ni les routines réelles.",autres=[(phrase('P-22.1',"Tu es incroyable et tu mélanges"),'P-22.1, même corps, message antérieur d’Élise du 16 septembre à 16 h 50 reproduit ; négation sur l’alcool et propos sur 50 %.')])
    ajout(32,(phrase('P-22.2',"Peu importe mes accusations du passé"),'P-22.2, Email 8, réponse d’Élise du 16 septembre 2016 à 16 h 07 -0400, paragraphe commençant ‘Tu m’as blessé’. Découpage du passage à l’intérieur de ce paragraphe.'),"Ce membre dit que le père a décidé de ne pas s'occuper des enfants 50 % du temps et lui demande ce qui lui fait croire qu'il en serait capable. Il documente la position quantitative et le reproche exprimés dans cet échange.","ECLAIRE_SEULEMENT","L'affirmation de l'expéditrice et sa contestation sont documentées ; leur vérité objective et leur rapport cumulatif avec P-19 restent à apprécier après l'ensemble. Le message de 16 h 50 n'est pas le texte courant de ce membre antérieur.")
    ajout(33,("Louis Philippe ta participation n'a jamais été de 50%.",'P-22.3, Email 295, réponse d’Élise du 16 septembre 2016 à 12 h 07 -0400, première phrase du corps MIME, présente mot pour mot.'),"Élise affirme que la participation n'a jamais été de 50 %, puis invoque les besoins des enfants et les difficultés de compréhension parentale. La pièce fournit cette position exprimée, pertinente au noyau invoqué au §9-G.","ECLAIRE_SEULEMENT","Cette réponse ne reprend pas elle-même le retrait de la formulation du §6 de P-19 rapporté dans P-20 ; elle ne prouve pas seule le patron, la proportion réelle des soins ou une intention mensongère.")
    ajout(34,(phrase('P-22.4',"Tu es incroyable et tu mélanges"),'P-22.4, Email 306, réponse d’Élise du 16 septembre 2016 à 16 h 50 -0400, premier paragraphe.'),"Élise nie avoir dit que le père passait son temps à se saouler et maintient qu'il ne s'occupait pas des enfants 50 % du temps. Le fil reproduit la contestation détaillée du demandeur sur les soins et les routines, ce qui localise la réponse dans son contexte.","ECLAIRE_SEULEMENT","La réponse est un objet de preuve du discours échangé. L'écart qualitatif/quantitatif et son poids au sein du patron ne sont pas transformés ici en conclusion cumulative ; aucune nouvelle observation n'est créée sur les autres messages du fil.")
    ajout(35,"9-routine","La lettre refuse le partage égal sur le fondement de l'âge et d'une routine récente tout en offrant des nuits. C'est une contribution documentaire identifiable à la continuité que le §9-G invoque.","ECLAIRE_SEULEMENT","L'offre et son motif sont établis comme propos. La sincérité du motif, le concert et l'ensemble du patron ne sont pas décidés par ce lien isolé.",autres=["9-nuitees"])
    ajout(36,(extrait('P-16','Les parties conviennent également','8. Dans le cadre'),'P-16, page 3/6, §7 ; projet et conditions de signature lus.'),"Le projet propose des accès croissants sur plusieurs années tout en maintenant la garde maternelle. Ces modalités précises éclairent son invocation comme corroboration de continuité au §9-G.","ECLAIRE_SEULEMENT","Le projet n'est pas signé et ne prouve pas l'exécution des modalités. La continuité fonctionnelle du patron est une inférence invoquée, dont le poids cumulatif n'est pas apprécié dans cette observation.")
    ajout(37,"18-premature","Me Ayoub exprime la satisfaction d'une progression mais rapporte que sa cliente juge prématuré un partage égal dès février 2016. Le document contient cette position de négociation que le §9-G invoque.","ECLAIRE_SEULEMENT","Le passage ne fixe pas de condition ou date de franchissement du seuil. Le motif et son expression ne démontrent pas, isolément, l'ensemble du patron ou une insincérité.")
    ajout(40,"42-abandon","La déclaration contient les reproches de refus de règlement (§3), d'absence de remboursement (§7), des possibilités d'emploi et d'un désaccord sur la contribution maternelle (§§14–20), puis la qualification d'abandon au §21. La relation porte sur ces déclarations effectivement consignées.","EN_ETABLIT_UNE_PARTIE","Le texte ne démontre pas la vérité de ces reproches. La date du serment est le 21 octobre 2019 ; le scan seul ne date pas la préparation ni la production au greffe. Le désaccord rapporté sur une contribution doit être distingué d'un refus de recevoir tout paiement.",
          autres=[("Puisque le défendeur refusait de régler le litige à l’amiable, j’ai été obligée de saisir le Tribunal afin de faire valoir les droits de nos enfants;","P-42, page 1/4, §3, transcription visuelle."),
                  ("Le ou vers le mois de 2019, lorsque le défendeur a appris que la Grand-mère paternelle des enfants voulait contribuer financièrement, monsieur s’est démontré en désaccord avec une telle décision;","P-42, page 3/4, §20, transcription visuelle ; le mois n'est pas renseigné dans l'original.")],
          ecarts=[{"type":"SENS","degre":"ETABLIT_EN_CADRANT_AUTREMENT","description":"Le §10-C résume P-42 comme un refus ‘d’accepter une contribution de sa mère’. Le §20 de P-42 dit que monsieur s’est montré ‘en désaccord avec une telle décision’ lorsqu'il a appris la contribution envisagée. La source établit ce désaccord allégué ; elle ne décrit pas dans ce passage un refus de recevoir un versement déterminé. Le résumé est plus affirmatif que le libellé."}])
    ajout(42,"40-choix","La dénonciation de 2023 contient effectivement une qualification du non-travail comme choix du demandeur. C'est le contenu que le §11 donne à examiner comme renouvellement du mécanisme décrit auparavant.","ECLAIRE_SEULEMENT","Le caractère de renouvellement ou de substitution est une inférence plaidée. L'observation n'établit ni sa fausseté consciente ni la qualification d'abus et ne compare pas cumulativement les actes.")
    ajout(43,"40-choix","La phrase sur le choix de ne pas travailler est présente au §8 ; le §7 rapporte plus de quatre cents offres pour le profil et le §6 mentionne la perte importante de revenus. Le scan porte aussi les signatures de Me Ayoub et d'Élise.","EN_ETABLIT_UNE_PARTIE","La signature de l'avocate est observée ; le processus matériel de rédaction ne résulte pas d'un historique de fichier. Les offres sont rapportées à l'audition de 2019 et la précarité est qualifiée de prétention, deux précisions nécessaires au regard du résumé du §11-A.",autres=["40-precarite","40-offres","40-serment"],
          ecarts=[{"type":"SENS","degre":"ETABLIT_EN_CADRANT_AUTREMENT","description":"Le §11-A dit que P-40 ‘reconnaissait’ la précarité financière. P-40 §6 écrit ‘Malgré les prétentions du demandeur eu égard à sa précarité financière’, tout en mentionnant sa perte importante de revenus. La pièce distingue donc l'existence de cette prétention de la mention de la perte ; présenter les deux comme une même reconnaissance efface ce cadrage."},
                  {"type":"DATE","degre":"ETABLIT_EN_CADRANT_AUTREMENT","description":"Les quatre cents offres de P-40 §7 sont expressément rapportées à une preuve présentée lors de l'audition du 4 novembre 2019. La dénonciation est de 2023, mais elle ne présente pas dans ce passage un inventaire de postes actualisé en 2023. Le dossier doit garder cette date du contenu rapporté."}])
    ajout(44,"40-objet","Le titre et les conclusions portent sur la compétence territoriale et le transfert à Longueuil ; le texte comprend aussi les représentations des §§6–8 sur les revenus, les offres et le choix de non-travail. Ces contenus correspondent au contraste procédural allégué au §11-B.","EN_ETABLIT_UNE_PARTIE","Le scan établit leur présence dans le même acte. Il n'établit pas la perte involontaire, toutes les démarches, le permis ou les contraintes ultérieures ; il ne tranche pas la pertinence juridique, l'intention, l'abus ou l'imputation de la dette de 2019.",autres=["40-choix","40-offres"])
    ajout(166,(extrait('P-2','Ensuite, Alexia vie',"Si j'étais ton avocate"),'P-2, page 1/2, paragraphe commençant ‘Ensuite, Alexia vie’ ; en-têtes identifiant Marie-Josée Ayoub et Élise.'),"Les mots sur la violence conjugale depuis la naissance et la sécurité et le développement compromis sont présents dans le courriel, lequel envisage ensuite des mesures d'urgence. Le §40 leur attribue la bonne source.","EN_ETABLIT_UNE_PARTIE","Le courriel établit ces déclarations et la conclusion envisagée d'un intervenant, pas une intervention réelle de la DPJ. La non-reprise de 2015 se vérifie séparément sur les autres pièces du paragraphe.")
    ajout(167,(extrait('P-7','Dans un deuxième temps','PAGE 2'),'P-7, page 1/3, paragraphe sur la garde ; lettre entière, dont p.3 blanche, lue.'),"La lettre de Me Poirier propose un partage 2-2-3 et dit ne voir aucune contre-indication. Ses pages ne reprennent pas les allégations de violence de P-2 : elle contribue au constat textuel limité du §40.","EN_ETABLIT_UNE_PARTIE","Une lettre de négociation de trois pages ne démontre pas l'absence de toute allégation à tout autre moment. L'absence dans ce texte ne prouve pas la cessation ou l'inexistence d'un danger réel.",attribution="Les citations de Me Ayoub au début du §40 sont dans P-2, pdf_manager.PDFDocument pk 1, lien 166. P-7, PDFDocument pk 2, est cité pour le texte des négociations de 2015, sans attribution de ces mots à son rédacteur.")
    ajout(168,"9-routine","La réponse de Me Ayoub motive son opposition à la garde partagée par l'âge et la routine récente ; les deux pages n'emploient pas le registre de violence de P-2. C'est le contenu de négociation auquel renvoie la seconde phrase du §40.","EN_ETABLIT_UNE_PARTIE","Ce constat concerne ce document et ses mots. Il ne permet pas de conclure à l'absence de danger ni à la totalité des échanges de 2015.",attribution="La citation de violence se trouve dans P-2, PDFDocument pk 1. P-9, PDFDocument pk 3, est examiné pour la non-reprise dans cette lettre ; pas de déplacement des citations de P-2 vers P-9.")
    ajout(169,(extrait('P-16','les enfants ne font pas','ATTENDU QUE'),'P-16, page 1/6, préambule ; projet complet et progression §7 lus.'),"Le projet énonce une absence de décision jeunesse et d'entente DPJ ; il offre des nuits et une progression sans reprendre les allégations de violence de P-2. Il apporte le texte de ce document à la comparaison limitée du §40.","EN_ETABLIT_UNE_PARTIE","Le projet demeure non signé ; la non-reprise du registre dans ces six pages ne prouve ni l'absence de danger réel ni l'ensemble des propos de 2015.",attribution="Le registre de violence cité au §40 est dans P-2, PDFDocument pk 1 ; le présent lien porte sur la non-reprise dans P-16, PDFDocument pk 5.")
    ajout(170,"19-dpj","La requête de novembre 2015 ne reprend pas les formules de violence conjugale de P-2 ; elle nie une décision, instance ou entente DPJ au §3 et repose sur d'autres reproches parentaux. La relation avec la seconde phrase du §40 est documentaire.","EN_ETABLIT_UNE_PARTIE","La requête n'est pas tout le dossier de 2015. Sa non-reprise n'établit pas la disparition d'un danger ni l'absence de toute intervention DPJ ; le terme ‘négociations’ est vérifié par les autres liens.",attribution="La citation initiale du §40 est retrouvée dans P-2, PDFDocument pk 1 ; P-19, Document pk 1, est examiné comme acte ultérieur ne la reprenant pas, sans lui attribuer cette citation.")
    ajout(271,"19-serment","L'affidavit d'Élise réitère tous les allégués de la requête, porte le jurat du 19 novembre 2015 et le dossier 505-04-024603-151. La requête et l'avis sont signés au nom de Me Adelia Ferreira p.11 et p.13, ce qui documente l'attribution de l'acte au §93.","ETABLIT_L_ENONCE","Portée limitée au fait documentaire de l'acte, de l'attestation, du dossier et de l'avocate signataire, sans déclaration sur la vérité objective des allégués. La rédaction est rattachée à la procureure signataire, sans observation du processus matériel d'écriture.")
    ajout(272,(extrait('P-2','La première chose que tu',"Je sais que l'aspect"),'P-2, page 1/2, début du premier paragraphe ; courriel entier lu.'),"Le courriel conseille à Élise de consulter un psychologue ; il n'attribue pas à Marc Pistorio le constat de difficulté paternelle présenté plus tard dans P-19. Il établit ce contenu et cette absence dans ses deux pages.","EN_ETABLIT_UNE_PARTIE","Le courriel ne décrit pas la requête de 2015 et ne démontre pas les propos réellement tenus en thérapie. L'absence dans ce texte n'est pas une preuve qu'aucun constat n'a jamais existé.")
    ajout(273,"19-therapie","P-19 §7 affirme qu'en thérapie il est ressorti une difficulté à assumer le rôle paternel, sans nommer Marc Pistorio ni citer un rapport de sa part. Le fichier et les renvois lus ne produisent pas un tel avis. La pièce est l'objet direct de la critique documentaire du §97.","EN_ETABLIT_UNE_PARTIE","Le texte situe toutefois une séparation et une thérapie en 2011 dans un contexte d'infidélité alléguée. Il manque une date précise, des paroles et les circonstances propres au constat attribué à la thérapie ; cela ne signifie pas absence de tout contexte. Le périmètre lu n'est pas l'intégralité du dossier judiciaire ancien.",
          ecarts=[{"type":"SENS","degre":"ETABLIT_EN_CADRANT_AUTREMENT","description":"Le §97 dit que la requête ne précisait ni date ni circonstances du constat thérapeutique. P-19 §7 donne néanmoins un cadre général : 2011, séparation d'un an, infidélité alléguée et thérapie. La critique reste documentée pour l'absence de date précise du constat, d'auteur et de paroles rapportées ; elle doit être distinguée d'une absence de tout repère temporel ou circonstanciel."}])
    for lien,cote in [(274,'P-66.1'),(275,'P-66.2'),(276,'P-66.3'),(277,'P-66.4')]:
        ajout(lien,(textes[cote].split('PAGE 1\n',1)[1].strip(),f'{cote}, PDF original, page 1/1, facture de Marc Pistorio, nom du client et lignes de séances.'),
              "La facture identifie Marc Pistorio comme psychologue et facture des séances à Louis-Philippe David. Elle fournit le repère documentaire de consultations auquel se rattache le §97, sans contenir de constat sur sa capacité paternelle.","ECLAIRE_SEULEMENT",
              "Une facture n'est pas un rapport ou une évaluation clinique ; elle ne prouve ni la teneur des séances ni l'absence d'un rapport au dossier de la requête. P-66.1 et P-66.2 reproduisent les mêmes références de facture 3506 et séances de janvier 2012 : aucune séance supplémentaire n'est comptée du seul fait des deux sous-cotes. Les autres membres de P-66 ont chacun leur observation distincte.")

    verifier_serie(constat,travail,ps)
    # Pour les citations prélevées, leur présence est contrôlée avant toute écriture.
    for o in ps:
        if o['methode_verbatim'].startswith('Extrait'):
            cote=fiches[o['liens'][0]]['cote']['cote']
            assert o['element_observe'] in corps.get(cote,textes[cote]),o['id']
    ecrire_identique_ou_nouveau(ARTEFACTS / 'serie_1/propositions.json',octets_json(ps))
    return ps


if __name__=='__main__':
    print(f'{len(preparer())} propositions préparées, grille 1.1, aucune validation LP')
